let source;
if(process.argv[2])source=fs.readFileSync(process.argv[2],'utf8');
else {const html=fs.readFileSync(path.join(__dirname,'../../index.html'),'utf8'),a=html.indexOf('const WORKER_JS='),b=html.indexOf('// ---------- 📂 settings',a),out={};vm.runInNewContext(html.slice(a,b)+';globalThis.result=WORKER_JS',out);source=out.result;}
new vm.Script(source.replace(/\bexport default\b/,'globalThis.proxy ='));
function harness(upstream,fast=false){const calls=[],context={URL,Request,Response,Headers,AbortController,ReadableStream,Uint8Array,TextEncoder,TextDecoder,Error,Number,String,JSON,Promise,setTimeout:fast?(f,ms)=>setTimeout(f,Math.min(ms,15)):setTimeout,clearTimeout,fetch:async(url,init)=>{calls.push({url,init});return upstream(url,init,calls.length)}};vm.createContext(context);vm.runInContext(source.replace(/\bexport default\b/,'globalThis.proxy ='),context);return{calls,run:(route,init={},env={})=>{const headers=new Headers(init.headers||{});if(init.origin!==null)headers.set('Origin',init.origin||origin);const o={...init,headers};delete o.origin;return context.proxy.fetch(new Request('https://proxy.example.com'+route,o),env);}};}
const pdf=()=>new Response('%PDF-fixture',{headers:{'Content-Type':'application/pdf','Content-Disposition':'attachment; filename="Lecture.pdf"'}});
const api=body=>({method:'POST',headers:{Authorization:auth,'Content-Type':'application/json'},body:typeof body==='string'?body:JSON.stringify(body)});
const valid={model:'kimi-k3.1-pro',messages:[{role:'user',content:'fixture'}],stream:true};
let count=0;const check=async(name,fn)=>{await fn();count++;console.log('OK '+name)};
(async()=>{
await check('foreign and absent origins cannot send any upstream request',async()=>{const h=harness(pdf);for(const init of [{origin:null},{origin:'https://foreign.example.com'}]){const r=await h.run('/url?u=https://files.example.com/a.pdf',init);assert.equal(r.status,403);assert.equal(r.headers.get('Access-Control-Allow-Origin'),null)}assert.equal(h.calls.length,0)});
await check('preflight is route-specific and has Vary Origin',async()=>{const h=harness(pdf),r=await h.run('/url',{method:'OPTIONS',headers:{'Access-Control-Request-Method':'GET'}});assert.equal(r.status,204);assert.equal(r.headers.get('Vary'),'Origin');assert.equal(r.headers.get('Access-Control-Allow-Methods'),'GET, OPTIONS');assert.equal((await h.run('/url',{method:'OPTIONS',headers:{'Access-Control-Request-Method':'POST'}})).status,405);assert.equal(h.calls.length,0)});
await check('unknown paths and wrong methods fail without fetch',async()=>{const h=harness(pdf);assert.equal((await h.run('/unknown')).status,404);for(const [p,m]of [['/drive','POST'],['/url','POST'],['/v1/chat/completions','GET']])assert.equal((await h.run(p,{method:m})).status,405);assert.equal(h.calls.length,0)});
await check('Drive IDs are bounded and only Google export targets are built',async()=>{const h=harness(pdf);for(const id of ['', '../secret', 'x'.repeat(201)])assert.equal((await h.run('/drive?id='+encodeURIComponent(id))).status,400);const r=await h.run('/drive?id=abcdefghijklmnop&k=slides');assert.equal(r.status,200);await r.arrayBuffer();assert.equal(h.calls[0].url,'https://docs.google.com/presentation/d/abcdefghijklmnop/export/pdf');assert.equal(h.calls[0].init.redirect,'manual')});
await check('normal public PDF/PPTX URLs preserve download metadata',async()=>{const h=harness(pdf);for(const ext of ['pdf','pptx']){const r=await h.run('/url?u='+encodeURIComponent('https://files.example.com/Arabic-'+ext+'.'+ext+'?signed=fixture'));assert.equal(r.status,200);assert.match(r.headers.get('Content-Disposition'),/Lecture.pdf/);assert.equal(r.headers.get('X-Content-Type-Options'),'nosniff');await r.arrayBuffer()}});
await check('literal private, loopback, alternate-IP, local, credentials and non-HTTPS URLs are rejected',async()=>{const h=harness(pdf),bad=['http://files.example.com/a.pdf','https://127.0.0.1/a.pdf','https://10.0.0.1/a.pdf','https://169.254.169.254/a.pdf','https://2130706433/a.pdf','https://0x7f000001/a.pdf','https://0177.0.0.1/a.pdf','https://[::1]/a.pdf','https://[::ffff:127.0.0.1]/a.pdf','https://localhost/a.pdf','https://host.internal/a.pdf','https://host.local/a.pdf','https://files.example.com:8443/a.pdf','https://user:pass@files.example.com/a.pdf','https://files.example.com/a.html','https://files.example.com/%ZZ.pdf'];for(const u of bad)assert.equal((await h.run('/url?u='+encodeURIComponent(u))).status,400,u);assert.equal(h.calls.length,0)});
await check('optional exact/subdomain allowlist is applied',async()=>{const h=harness(pdf),env={FILE_HOSTS:'files.example.com, *.trusted.example.com'};assert.equal((await h.run('/url?u=https://other.example.com/a.pdf',{},env)).status,400);for(const host of ['files.example.com','a.trusted.example.com']){const r=await h.run('/url?u=https://'+host+'/a.pdf',{},env);assert.equal(r.status,200);await r.arrayBuffer()}});
await check('every file redirect is manual and revalidated',async()=>{const h=harness((url,init,n)=>n===1?new Response(null,{status:302,headers:{Location:'https://cdn.example.com/download?signed=fixture'}}):pdf());const r=await h.run('/url?u=https://files.example.com/a.pdf');assert.equal(r.status,200);await r.arrayBuffer();assert.equal(h.calls.length,2);assert(h.calls.every(c=>c.init.redirect==='manual'));const bad=harness(()=>new Response(null,{status:302,headers:{Location:'https://127.0.0.1/secret'}}));assert.equal((await bad.run('/url?u=https://files.example.com/a.pdf')).status,502);assert.equal(bad.calls.length,1)});
await check('Drive redirects cannot leave Google download domains',async()=>{const h=harness(()=>new Response(null,{status:302,headers:{Location:'https://foreign.example.com/download'}}));assert.equal((await h.run('/drive?id=abcdefghijklmnop')).status,502);assert.equal(h.calls.length,1)});
await check('redirect loops stop at the configured hop bound',async()=>{const h=harness(()=>new Response(null,{status:302,headers:{Location:'/next'}}));assert.equal((await h.run('/url?u=https://files.example.com/a.pdf')).status,502);assert.equal(h.calls.length,5)});
await check('HTML success pages and oversized declared downloads are rejected',async()=>{const h=harness(()=>new Response('<html>sign in</html>',{headers:{'Content-Type':'text/html'}}));assert.equal((await h.run('/url?u=https://files.example.com/a.pdf')).status,502);const big=harness(()=>new Response(null,{headers:{'Content-Length':String(61*1024*1024),'Content-Type':'application/pdf'}}));assert.equal((await big.run('/url?u=https://files.example.com/a.pdf')).status,413)});
await check('missing authorization and wrong JSON content type are rejected',async()=>{const h=harness(pdf);assert.equal((await h.run('/v1/chat/completions',{method:'POST',body:'{}'})).status,401);assert.equal((await h.run('/v1/chat/completions',{method:'POST',headers:{Authorization:auth,'Content-Type':'text/plain'},body:'{}'})).status,415);assert.equal(h.calls.length,0)});
await check('malformed and wrong-type JSON is rejected before upstream',async()=>{const h=harness(pdf);for(const body of ['{bad','null','[]','{}','{"model":5,"messages":[]}','{"model":"kimi-k3.1-pro","messages":[]}'])assert.equal((await h.run('/v1/chat/completions',api(body))).status,400);assert.equal(h.calls.length,0)});
await check('request bytes are bounded even without Content-Length',async()=>{const h=harness(pdf),r=await h.run('/v1/chat/completions',api('x'.repeat(3*1024*1024+1)));assert.equal(r.status,413);assert.equal(h.calls.length,0)});
await check('Kimi target is fixed and only explicit cn=1 selects .cn',async()=>{const h=harness(()=>new Response('{}',{headers:{'Content-Type':'application/json'}}));for(const [q,host]of [['','api.moonshot.ai'],['?cn=0&target=https://evil.example.com','api.moonshot.ai'],['?cn=1','api.moonshot.cn']]){const r=await h.run('/v1/chat/completions'+q,api(valid));await r.text();const c=h.calls.at(-1);assert.equal(c.url,'https://'+host+'/v1/chat/completions');assert.equal(c.init.headers.Authorization,auth);assert.equal(c.init.redirect,'manual')}});
await check('Kimi redirects do not forward the bearer credential',async()=>{const h=harness(()=>new Response(null,{status:302,headers:{Location:'https://foreign.example.com/steal'}}));const r=await h.run('/v1/chat/completions',api(valid));assert.equal(r.status,502);assert.equal(h.calls.length,1);assert(!(await r.text()).includes('fixture-valid-key'))});
await check('rate-limit headers and status survive proxying and CORS',async()=>{const h=harness(()=>new Response('{"error":"rate"}',{status:429,headers:{'Content-Type':'application/json','Retry-After':'30','X-RateLimit-Reset':'123'}})),r=await h.run('/v1/chat/completions',api(valid));assert.equal(r.status,429);assert.equal(r.headers.get('Retry-After'),'30');assert.equal(r.headers.get('X-RateLimit-Reset'),'123');assert.match(r.headers.get('Access-Control-Expose-Headers'),/Retry-After/);await r.text()});
await check('streaming content and bounded unknown-length response work',async()=>{const h=harness(()=>new Response('data: {"fixture":true}\n\ndata: [DONE]\n',{headers:{'Content-Type':'text/event-stream'}})),r=await h.run('/v1/chat/completions',api(valid));assert.match(await r.text(),/\[DONE\]/);const big=harness(()=>new Response(new Uint8Array(8*1024*1024+1),{headers:{'Content-Type':'text/event-stream'}})),b=await big.run('/v1/chat/completions',api(valid));await assert.rejects(()=>b.arrayBuffer(),/stream failed/)});
await check('network errors are generic and never include upstream exception secrets',async()=>{const h=harness(()=>{throw new Error('fixture-sensitive-upstream-value')});const r=await h.run('/v1/chat/completions',api(valid));assert.equal(r.status,502);assert.equal(await r.text(),'upstream unavailable')});
await check('hung upstream requests are aborted and return timeout',async()=>{let aborted=false;const h=harness((u,init)=>new Promise((resolve,reject)=>init.signal.addEventListener('abort',()=>{aborted=true;reject(new Error('aborted'));})),true),r=await h.run('/v1/chat/completions',api(valid));assert.equal(r.status,504);assert(aborted)});
await check('slow request-body streams time out instead of hanging before fetch',async()=>{const h=harness(pdf,true),body=new ReadableStream({start(){},cancel(){}}),r=await h.run('/v1/chat/completions',{method:'POST',headers:{Authorization:auth,'Content-Type':'application/json'},body,duplex:'half'});assert.equal(r.status,504);assert.equal(h.calls.length,0)});
console.log(count+' proxy endpoint checks passed');
})().catch(e=>{console.error(e.stack);process.exitCode=1});
